title: $:/Lithic/Patches/AutoCloseKeepOpen.js
type: application/javascript
module-type: startup

Watches for the Text tool's specific style options (Align/Font) and automatically 
turns off "Keep Style Menu Open" to prevent the shape.id crash bug.
\*/
(function () {
    "use strict";

    exports.name = "lithic-auto-close-keep-open";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    exports.startup = function () {

        function disableKeepOpen() {
            var clicked = false;

            // 1. Check Preferences Menu Button by ID
            var keepOpenBtn = document.getElementById('TD-Styles-Keep-Open');
            if (keepOpenBtn && (keepOpenBtn.getAttribute('data-state') === 'checked' || keepOpenBtn.getAttribute('aria-checked') === 'true')) {
                keepOpenBtn.click();
                clicked = true;
            }

            // 2. Check Palette Menu option by text
            var spans = document.querySelectorAll('.tw-whiteboard-tldraw-container span');
            for (var i = 0; i < spans.length; i++) {
                if (spans[i].textContent === "Keep Style Menu Open" || spans[i].textContent === "Keep Open") {
                    var wrapper = spans[i].closest('button, .c-kuOiws');
                    if (wrapper && wrapper.id !== 'TD-Styles-Keep-Open') {
                        // Look for the checked state
                        if (wrapper.querySelector('[data-state="checked"]') || wrapper.getAttribute('data-state') === 'checked') {
                            wrapper.click();
                            clicked = true;
                        }
                    }
                }
            }

            if (clicked) {
                setTimeout(function() {
                    var escEvent = new KeyboardEvent('keydown', {
                        key: 'Escape',
                        code: 'Escape',
                        keyCode: 27,
                        which: 27,
                        bubbles: true,
                        cancelable: true
                    });
                    document.dispatchEvent(escEvent);
                }, 10);
            }
        }

        if (typeof document !== "undefined") {
            var observer = new MutationObserver(function(mutations) {
                // If the specific Text tool UI is present in the DOM
                if (document.getElementById('TD-Styles-Align-Container')) {
                    disableKeepOpen();
                }
            });

            // Observe the document body for any DOM additions/removals
            observer.observe(document.body, { childList: true, subtree: true });
        }
    };

})();
"},"$:/Lithic/Patches/BootDelay/StartupScript.js":{"title":"$:/Lithic/Patches/BootDelay/StartupScript.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/BootDelay/StartupScript.js
type: application/javascript
module-type: startup

Sets a state flag after the TiddlyWiki boot sequence is completely finished.
This flag is used to delay the rendering of React widgets (like the whiteboard)
to prevent them from interfering with TiddlyWiki's initial core DOM setup.
\*/
(function(){
"use strict";

exports.name = "lithic-boot-delay-flag";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
    // Wait a brief moment after the synchronous startup completes
    // to ensure the DOM is fully settled.
    setTimeout(function() {
        $tw.wiki.setText("$:/state/Lithic/BootComplete", "text", null, "yes");
        console.log("[Lithic] Boot sequence completely settled. BootComplete flag set to 'yes'.");
    }, 250);
};

})();
"},"$:/Lithic/Patches/IsolateDoubleClicks":{"title":"$:/Lithic/Patches/IsolateDoubleClicks","module-type":"startup","tags":"","type":"application/javascript","text":"/*\
title: $:/Lithic/Patches/IsolateDoubleClicks
type: application/javascript
module-type: startup

Prevents double-click events inside the Tldraw widget from bubbling up 
and triggering the Streams "double click to edit" action.
\*/
(function () {
    "use strict";

    exports.name = "lithic-isolate-double-clicks";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    exports.startup = function () {

        var addIsolation = function (node) {
            // Avoid attaching twice
            if (node.dataset.lithicDblClickIsolated) return;

            // Listen for double clicks and kill them before they bubble to Streams
            node.addEventListener('dblclick', function (e) {
                e.stopPropagation();
                // console.log("ðŸ›¡ï¸ Lithic: Stopped double-click from triggering Streams.");
            }, false); // Bubble phase

            node.dataset.lithicDblClickIsolated = "active";
        };

        // Watch for new Tldraw containers appearing in the DOM
        var observer = new MutationObserver(function (mutations) {
            mutations.forEach(function (mutation) {
                mutation.addedNodes.forEach(function (node) {
                    if (node.nodeType !== 1) return;

                    // 1. Check if the added node IS the container
                    if (node.classList.contains('tw-whiteboard-tldraw-container')) {
                        addIsolation(node);
                    }
                    // 2. Check if the container is INSIDE the added node
                    else if (node.querySelector) {
                        var containers = node.querySelectorAll('.tw-whiteboard-tldraw-container');
                        for (var i = 0; i < containers.length; i++) {
                            addIsolation(containers[i]);
                        }
                    }
                });
            });
        });

        if (document.body) {
            observer.observe(document.body, { childList: true, subtree: true });
        }
    };

})();"},"$:/Lithic/Patches/Whiteboard/ActionDispatchPaste.js":{"title":"$:/Lithic/Patches/Whiteboard/ActionDispatchPaste.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/Lithic/Patches/Whiteboard/ActionDispatchPaste.js
type: application/javascript
module-type: widget

Action widget to dispatch a synthetic paste event containing the comptext input to Tldraw.
\*/
(function(){
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var ActionDispatchPaste = function(parseTreeNode,options) {
    this.initialise(parseTreeNode,options);
};

ActionDispatchPaste.prototype = new Widget();

ActionDispatchPaste.prototype.render = function(parent,nextSibling) {
    this.computeAttributes();
    this.execute();
};

ActionDispatchPaste.prototype.execute = function() {
    this.tiddlerName = this.getAttribute("tiddler", "$:/temp/whiteboard-comptext-input");
    this.boardStateTiddler = "$:/state/Whiteboard/PageLayout/tiddler";
};

ActionDispatchPaste.prototype.refresh = function(changedTiddlers) {
    var changedAttributes = this.computeAttributes();
    if(changedAttributes.tiddler) {
        this.refreshSelf();
        return true;
    }
    return this.refreshChildren(changedTiddlers);
};

// Generates a random UUID v4 ending with 'c001' so we can target it via CSS
function generateUUID() {
    var base = 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxc001'.replace(/[xy]/g, function(c) {
        var r = Math.random() * 16 | 0, v = c === 'x' ? r : (r & 0x3 | 0x8);
        return v.toString(16);
    });
    return base;
}

ActionDispatchPaste.prototype.invokeAction = function(triggeringWidget,event) {
    var text = $tw.wiki.getTiddlerText(this.tiddlerName);
    if (!text) return true; // nothing to paste

    // Determine which whiteboard is currently active
    var currentBoard = $tw.wiki.getTiddlerText(this.boardStateTiddler);
    if (!currentBoard) {
        // Fallback to the first whiteboard modified
        var tiddlers = $tw.wiki.filterTiddlers("[all[shadows+tiddlers]field:type[application/tldr]!prefix[$:/temp]!sort[modified]first[]]");
        if (tiddlers.length > 0) currentBoard = tiddlers[0];
    }

    if (!currentBoard) return true;

    var boardText = $tw.wiki.getTiddlerText(currentBoard);
    if (!boardText) return true;

    try {
        var data = JSON.parse(boardText);
        var page = data.document.pages.page;

        // Find the highest childIndex
        var maxIndex = 0;
        for (var shapeId in page.shapes) {
            var shape = page.shapes[shapeId];
            if (shape.childIndex > maxIndex) maxIndex = shape.childIndex;
        }

        var newShapeId = generateUUID();

        // Create the new sticky note
        var newShape = {
            id: newShapeId,
            type: "sticky",
            name: "Sticky",
            parentId: "page",
            childIndex: maxIndex + 1,
            point: [200, 200], // We can spawn it top-left or try to center it
            size: [300, 300],
            text: text,
            rotation: 0,
            style: {
                color: "black",
                size: "small",
                isFilled: false,
                dash: "draw",
                scale: 1,
                font: "sans",
                textAlign: "middle"
            }
        };

        // Center it around the camera if possible
        if (data.pageStates && data.pageStates.page && data.pageStates.page.camera) {
            var cam = data.pageStates.page.camera.point;
            newShape.point = [-(cam[0]) + 300, -(cam[1]) + 300];
        }

        page.shapes[newShapeId] = newShape;

        // Write it back to the tiddler
        $tw.wiki.setText(currentBoard, "text", null, JSON.stringify(data));

    } catch(e) {
        console.error("Failed to inject shape into whiteboard JSON", e);
    }

    return true; // Action was invoked
};

exports["action-dispatch-paste"] = ActionDispatchPaste;

})();
"},"$:/Lithic/Patches/Whiteboard/ComptextBridge.js":{"title":"$:/Lithic/Patches/Whiteboard/ComptextBridge.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/Whiteboard/ComptextBridge.js
type: application/javascript
module-type: startup

Listens for hotkeys (/, [, {) to trigger the floating Comptext UI in the whiteboard.
\*/
(function () {
    "use strict";

    exports.name = "lithic-whiteboard-comptext-bridge";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    exports.startup = function () {
        if (typeof window === "undefined" || typeof $tw === "undefined") return;

        window.addEventListener('keydown', function(event) {
            // Check if we are in the whiteboard
            var whiteboardContainer = document.querySelector('.tw-whiteboard-layout-container');
            if (!whiteboardContainer) return;

            // Do not trigger if a modal or popup is already open
            var isPopupOpen = $tw.wiki.getTiddlerText("$:/state/Whiteboard/ComptextPopup") === "open";
            if (isPopupOpen) return;

            // Check if the user is typing in an input field or contenteditable (e.g. existing sticky note)
            var active = document.activeElement;
            if (active) {
                var tag = active.tagName.toUpperCase();
                if (tag === 'INPUT' || tag === 'TEXTAREA' || active.isContentEditable) {
                    return;
                }
            }

            // Detect hotkeys
            var key = event.key;
            if (key === '/' || key === '[' || key === '{') {
                // Prevent default Tldraw behaviors or scrolling
                event.preventDefault();
                event.stopPropagation();

                var prefill = key;
                if (key === '[') prefill = '[[';
                if (key === '{') prefill = '{{';

                // Set the temporary text
                $tw.wiki.setText("$:/temp/whiteboard-comptext-input", "text", null, prefill);

                // Open the popup
                $tw.wiki.setText("$:/state/Whiteboard/ComptextPopup", "text", null, "open");

                // We need to focus the edit-text widget. We can do it by waiting for the DOM to update.
                setTimeout(function() {
                    var input = document.querySelector('.lithic-floating-comptext-input');
                    if (input) {
                        input.focus();
                        // Move cursor to the end
                        input.setSelectionRange(prefill.length, prefill.length);
                    }
                }, 100);
            }
        }, true); // Use capture phase so Tldraw doesn't swallow it first!

        window.addEventListener('click', function(event) {
            // Intercept clicks on the "Insert Media" button in Tldraw
            var mediaBtn = event.target.closest('#TD-PrimaryTools-Image');
            if (mediaBtn) {
                event.preventDefault();
                event.stopPropagation();

                // Clear the input and open the popup
                $tw.wiki.setText("$:/temp/whiteboard-comptext-input", "text", null, "");
                $tw.wiki.setText("$:/state/Whiteboard/ComptextPopup", "text", null, "open");

                // Focus the input
                setTimeout(function() {
                    var input = document.querySelector('.lithic-floating-comptext-input');
                    if (input) {
                        input.focus();
                    }
                }, 100);
            }
        }, true);

    };

})();
"},"$:/Lithic/Patches/Whiteboard/DeleteKeySimulator.js":{"title":"$:/Lithic/Patches/Whiteboard/DeleteKeySimulator.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/Whiteboard/DeleteKeySimulator.js
type: application/javascript
module-type: startup

Simulates a click on the tldraw trash can icon when the Delete or Backspace key is pressed,
as TiddlyWiki or Streams sometimes swallows keyboard shortcuts.
\*/
(function () {
    "use strict";

    exports.name = "lithic-whiteboard-delete-simulator";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    exports.startup = function () {
        if (typeof document !== "undefined") {
            document.addEventListener('keydown', function(e) {
                // Only respond to Delete or Backspace
                if (e.key !== 'Delete' && e.key !== 'Backspace') return;

                console.log("[DeleteSimulator] Caught key:", e.key, "Target:", e.target);

                if (!e.target) return;

                // Ignore if typing in an input
                if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA' || e.target.isContentEditable) {
                    console.log("[DeleteSimulator] Ignored because target is input/textarea/contenteditable.");
                    return;
                }

                // Also ignore if inside the tldraw text editor container
                if (typeof e.target.closest === 'function') {
                    if (e.target.closest('.tl-text-editor') || e.target.closest('.c-fOQRlS') || e.target.closest('.tl-absolute')) {
                        console.log("[DeleteSimulator] Ignored because target is inside tldraw text editor.");
                        return;
                    }
                }

                var deleteBtnWrapper = document.getElementById('TD-Delete');
                if (deleteBtnWrapper) {
                    console.log("[DeleteSimulator] Found #TD-Delete wrapper in DOM.");
                    var deleteBtn = deleteBtnWrapper.querySelector('button');
                    if (deleteBtn) {
                        console.log("[DeleteSimulator] Found button inside wrapper! Dispatching pointerdown and click...");

                        var eventInit = { bubbles: true, cancelable: true, button: 0 };
                        deleteBtn.dispatchEvent(new PointerEvent('pointerdown', eventInit));
                        deleteBtn.dispatchEvent(new MouseEvent('mousedown', eventInit));
                        deleteBtn.dispatchEvent(new PointerEvent('pointerup', eventInit));
                        deleteBtn.dispatchEvent(new MouseEvent('mouseup', eventInit));
                        deleteBtn.click();

                        e.preventDefault();
                        e.stopPropagation();
                    } else {
                        console.log("[DeleteSimulator] ERROR: Could not find <button> inside #TD-Delete");
                    }
                } else {
                    console.log("[DeleteSimulator] #TD-Delete not found in DOM.");
                }
            }, true); // Use capture phase to act before other handlers
        }
    };

})();
"},"$:/Lithic/Patches/Whiteboard/LandscapeGate":{"title":"$:/Lithic/Patches/Whiteboard/LandscapeGate","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* The whiteboard layout is built for a wide screen: the board is a tldraw
   canvas and the top bar is a fixed 400px strip of controls. Held in portrait,
   a phone renders an unusable sliver of both. So the WhiteBoard page layout
   mounts a gate (see .lithic-wb-rotate-gate there) and this sheet decides when
   to show it: never in landscape, never on a desktop, and in portrait only on
   a touch device no wider than a tablet.

   Three conditions, each with a job:
     pointer: coarse     a phone or tablet, never a resized desktop window
     orientation         portrait only, so rotating hides the gate instantly
     max-width: 1024px   leaves portrait monitors out of it

   Pure CSS: no script runs, the check happens before the first paint, and no
   touch reaches the canvas while the gate is up.

   The gate is a message, not a page, so nothing behind it may move either. A
   finger dragged on the gate is swallowed by touch-action, and the document
   behind it is given nothing to scroll. Both are guarded by the gate's own
   presence, so they exist exactly while the whiteboard layout is mounted:
   leaving the layout (or rotating, which drops the media query) restores
   ordinary scrolling in the same frame. */

.lithic-wb-rotate-gate {
    display: none;
}

@media (pointer: coarse) and (orientation: portrait) and (max-width: 1024px) {
    html:has(.lithic-wb-rotate-gate),
    body:has(.lithic-wb-rotate-gate) {
        overflow: hidden !important;
        overscroll-behavior: none;
    }

    .lithic-wb-rotate-gate {
        position: fixed;
        top: 0;
        right: 0;
        bottom: 0;
        left: 0;
        z-index: 9999999;
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 1rem;
        padding: 2rem;
        box-sizing: border-box;
        text-align: center;
        background: var(--lithic-c-page);
        color: var(--lithic-c-foreground);
        touch-action: none;
    }
}

.lithic-wb-rotate-gate-glyph {
    width: 4.5rem;
    height: 4.5rem;
    opacity: 0.85;
}

.lithic-wb-rotate-gate-title {
    margin: 0;
    font-size: 1.2em;
    font-weight: bold;
}

.lithic-wb-rotate-gate-hint {
    margin: 0;
    max-width: 22em;
    color: var(--lithic-c-foreground-muted);
}

.lithic-wb-rotate-gate-exit {
    margin-top: 0.75rem;
    padding: 0.4rem 1.1rem;
    border: 1px solid var(--lithic-c-menu-border);
    border-radius: 2rem;
    background: var(--lithic-c-menu-bg);
    color: var(--lithic-c-menu-fg);
    font: inherit;
    cursor: pointer;
}

.lithic-wb-rotate-gate-exit:hover {
    background: color-mix(in srgb, var(--lithic-c-menu-fg) 10%, var(--lithic-c-menu-bg));
}"},"$:/Lithic/Patches/Whiteboard/LongPressRightClick.js":{"title":"$:/Lithic/Patches/Whiteboard/LongPressRightClick.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/Whiteboard/LongPressRightClick.js
type: application/javascript
module-type: startup

Consume Android hold-touch-to-right-click (long-press) events inside the
whiteboard, while preserving deliberate right-clicks.

On Android / stylus devices, holding the stylus or finger still for a moment
while drawing registers as a `contextmenu` event, which opens tldraw's own
context menu mid-stroke. Debouncing or styles cannot help here, and we do NOT
want to remove the right-click menu entirely: desktop mouse right-click must
keep working, and the menu must stay available everywhere else in the wiki.

How this patch works:

1. tldraw's menu is opened by React's `onContextMenu` handler on the Radix
   trigger wrapping the whole board (the board renders inside
   `div.tw-whiteboard-tldraw-container`). React attaches its listeners at the
   mount container, so a document-level CAPTURE listener runs first: calling
   `preventDefault()` + `stopImmediatePropagation()` there prevents both the
   browser's native long-press menu and tldraw's menu from ever opening.
2. The patch only acts on `contextmenu` events whose target is inside the
   whiteboard surface (`.tw-whiteboard-tldraw-container, .tl-container`).
3. Touch/stylus derivation is detected two ways:
   - `event.sourceCapabilities.firesTouchEvents` (Chrome/Android reports true
     for touch- and stylus-generated events),
   - else a capture-phase `pointerdown` tracker: any non-mouse pointer
     (`touch`/`pen`/`stylus`) in the last 2s marks the gesture as touch-based.
   Mouse pointerdowns (right-click) are never treated as touch.
4. A hold time gate separates long-press from deliberate touch right-clicks:
   Android fires its long-press `contextmenu` only after the hold timeout
   (>~500ms after pointerdown), while a stylus barrel-button right-click fires
   almost immediately. Events arriving <200ms after the pointerdown pass
   through, so stylus-button and two-finger right-clicks still work.
5. Targets that are inputs/textareas or `contentEditable` are passed through
   unchanged, so long-press copy/paste while editing board text keeps the
   native menu.

Not a width/media-query fix: this listens on the event source (touch/stylus
vs. mouse), so it works regardless of viewport size or device category.

The wiki's own context menu (ahanniga `context-menu` plugin) already returns
early for `.tw-whiteboard-layout-container`, so this patch is the only menu
suppression the whiteboard needs.

Diagnostics: every decision is recorded on `window.__lithicLongPressProbe`
({suppressed, reason}) for testing and debugging.
\*/
(function(){
"use strict";

exports.name = "lithic-whiteboard-long-press-right-click";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
	if(typeof window === "undefined" || typeof document === "undefined") {
		return;
	}

	var SCOPE_SELECTOR = ".tw-whiteboard-tldraw-container, .tl-container";
	// A touch/stylus contextmenu arriving this soon after pointerdown is a
	// deliberate right-click (stylus barrel button, two-finger tap), not the
	// Android long-press, which only fires after the hold timeout.
	var LONG_PRESS_MIN_MS = 200;
	// Touch gestures older than this no longer count as "the current gesture".
	var TOUCH_GESTURE_WINDOW_MS = 2000;

	var lastPointerDown = {type: "mouse", time: 0};

	var probe = {suppressed: false, reason: ""};
	window.__lithicLongPressProbe = probe;

	// Track the most recent pointerdown of ANY kind (with its pointerType).
	// Mouse right-clicks overwrite the entry, so a mouse click right after a
	// touch gesture is never mistaken for it.
	document.addEventListener("pointerdown", function(event) {
		lastPointerDown = {type: event.pointerType || "mouse", time: Date.now()};
	}, true);

	function isEditable(target) {
		return !!(target.closest && (target.closest("input, textarea") || target.isContentEditable));
	}

	document.addEventListener("contextmenu", function(event) {
		var target = event.target;
		// Only consume hold-touch right-clicks inside the whiteboard surface.
		if(!target || !target.closest || !target.closest(SCOPE_SELECTOR)) {
			probe.suppressed = false;
			probe.reason = "outside-whiteboard";
			return;
		}
		// Keep the native copy/paste menu while editing text on the board.
		if(isEditable(target)) {
			probe.suppressed = false;
			probe.reason = "editable-target";
			return;
		}
		// Touch/stylus-derived, or mouse/keyboard?
		var capsFiresTouch = !!(event.sourceCapabilities && event.sourceCapabilities.firesTouchEvents === true);
		var elapsed = Date.now() - lastPointerDown.time;
		var sawRecentNonMouse = lastPointerDown.type !== "mouse" && elapsed < TOUCH_GESTURE_WINDOW_MS;
		if(!capsFiresTouch && !sawRecentNonMouse) {
			probe.suppressed = false;
			probe.reason = "mouse-or-keyboard";
			return;
		}
		// Too fast to be a long-press -> deliberate touch right-click.
		if(elapsed < LONG_PRESS_MIN_MS) {
			probe.suppressed = false;
			probe.reason = "fast-touch-right-click";
			return;
		}
		// Hold-touch-to-right-click inside the whiteboard: consume it.
		event.preventDefault();
		event.stopImmediatePropagation();
		probe.suppressed = true;
		probe.reason = "touch-long-press";
	}, true);
};

})();"},"$:/Lithic/Patches/Whiteboard/MobileViewport":{"title":"$:/Lithic/Patches/Whiteboard/MobileViewport","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* A phone's browser draws its own chrome over the page, so 100vh is the
   viewport with that chrome hidden, not the one the reader can see. The board
   is sized in vh: the page layout passes height="100vh" to the whiteboard
   widget, which writes it as an inline height on .tw-whiteboard-tldraw-container,
   and tldraw anchors its bottom toolbar to the bottom of that box. On a phone
   the box therefore runs on under the browser chrome, the toolbar is anchored
   below the visible area, and no tool is reachable until the page is scrolled.

   dvh is the viewport that is actually on screen, so the box ends where the
   reader's screen ends and the toolbar arrives with it. The vh line stays in
   front of the dvh line for engines that have no dvh, and !important is the
   only way to reach a height the widget set inline. Scoped to a coarse
   pointer, so a desktop window keeps its 100vh. */

@media (pointer: coarse) {
    .tw-whiteboard-tldraw-container {
        height: 100vh !important;
        height: 100dvh !important;
    }
}"},"$:/Lithic/Patches/Whiteboard/PageMenuOverflow":{"title":"$:/Lithic/Patches/Whiteboard/PageMenuOverflow","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* Keep tldraw menus inside the viewport when they contain many items. The
   stock bundle hardcodes max-height: 100vh on menu panels, which are anchored
   below their trigger - so on the full-screen whiteboard layout a panel
   extends past the bottom of the screen and the last item ("Create page")
   can never be scrolled into view. Radix already computes the true available
   space and exposes it as CSS vars; use those instead of the hardcoded 100vh.
   The dropdown var covers the page select/zoom/style menus; the context-menu
   var covers right-click menus (opened at the cursor). Both fall back to the
   stock 100vh when absent, so nothing else is affected. */

.tw-whiteboard-tldraw-container [role="menu"] {
    max-height: var(
        --radix-dropdown-menu-content-available-height,
        var(--radix-context-menu-content-available-height, 100vh)
    ) !important;
}"},"$:/Lithic/Patches/Whiteboard/PageNav.js":{"title":"$:/Lithic/Patches/Whiteboard/PageNav.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/Whiteboard/PageNav.js
type: application/javascript
module-type: startup

Adds prev/next page navigation buttons immediately to the right of the tldraw
page-select dropdown (the #TD-Page trigger in the upper-left #TD-MenuPanel).
This is pure whiteboard-internal navigation: the buttons drive the live
TldrawApp via app.changePage() and know nothing about TiddlyWiki's own board
selector in the top bar.

The page dropdown in this build ships without flanking chevrons, so helpers
are mounted next to it. Clicking calls changePage on the actual tldraw app
instance, reached by walking the React fiber tree up from the trigger to the
TldrawContext.Provider (whose memoizedProps.value IS the app).

Both glyphs (chevron + bullet) are rendered into each button up front and the
visible one is chosen with pure CSS via :disabled - navigating never mutates
the button's DOM, so rapid/spam clicks can never be swallowed by the browser
suppressing a click whose mousedown target was removed mid-press. The app is
resolved fresh from the live trigger at click time (with a cached fallback),
so transient React re-renders can't drop a click either.
\*/
(function () {
    "use strict";

    exports.name = "lithic-whiteboard-page-nav";
    exports.platforms = ["browser"];
    exports.after = ["startup"];
    exports.synchronous = true;

    var BUTTON_CLASS = "lithic-wb-page-nav-btn";
    var SCAN_DEBOUNCE_MS = 25;

    // Stroke-style left/right chevrons (Feather icon set, 24x24 viewBox) so
    // the buttons read unambiguously as prev/next navigation.
    var ICON_PREV = '<polyline points="15 18 9 12 15 6"/>';
    var ICON_NEXT = '<polyline points="9 18 15 12 9 6"/>';

    // Small bullet shown in place of the chevron when the button is disabled
    // (no further page in that direction).
    var DOT = '<circle cx="5" cy="5" r="3.5"/>';

    function chevronSvg(direction) {
        return '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" ' +
            'stroke="currentColor" stroke-width="2.5" stroke-linecap="round" ' +
            'stroke-linejoin="round" xmlns="http://www.w3.org/2000/svg">' +
            (direction === "prev" ? ICON_PREV : ICON_NEXT) +
            "</svg>";
    }

    function dotSvg() {
        return '<svg width="10" height="10" viewBox="0 0 10 10" ' +
            'fill="currentColor" xmlns="http://www.w3.org/2000/svg">' +
            DOT +
            "</svg>";
    }

    function directionOf(btn) {
        return btn.classList.contains("lithic-wb-page-prev") ? "prev" : "next";
    }

    function makeButton(direction) {
        var btn = document.createElement("button");
        btn.type = "button";
        btn.className = BUTTON_CLASS + " lithic-wb-page-" + direction;
        btn.setAttribute("aria-label", direction === "prev" ? "Previous page" : "Next page");
        btn.title = direction === "prev" ? "Previous page" : "Next page";
        // Both glyphs are always present; CSS shows the chevron when enabled
        // and the bullet when disabled (no DOM mutation while interacting).
        btn.innerHTML =
            '<span class="lithic-wb-glyph lithic-wb-glyph-chevron">' + chevronSvg(direction) + "</span>" +
            '<span class="lithic-wb-glyph lithic-wb-glyph-dot">' + dotSvg() + "</span>";
        return btn;
    }

    // Walk the React fiber tree up from a page dropdown trigger to find the
    // live TldrawApp. The TldrawContext.Provider fiber's memoizedProps.value
    // is the app instance itself.
    function findAppFrom(trigger) {
        if (!trigger) return null;
        var key = null;
        for (var prop in trigger) {
            if (prop.indexOf("__reactFiber$") === 0 || prop.indexOf("__reactInternalInstance$") === 0) {
                key = prop;
                break;
            }
        }
        if (!key) return null;
        var fiber = trigger[key];
        var guard = 0;
        while (fiber && guard++ < 300) {
            var props = fiber.memoizedProps;
            if (props && props.value && typeof props.value === "object") {
                var candidate = props.value;
                if (typeof candidate.changePage === "function" &&
                    candidate.document && candidate.document.pages && candidate.appState) {
                    return candidate;
                }
            }
            fiber = fiber.return;
        }
        return null;
    }

    // The page dropdown trigger can be replaced by tldraw re-renders; find the
    // CURRENT trigger that lives in the same menu panel as the button.
    function liveTrigger(btn) {
        var panel = btn.closest ? (btn.closest("#TD-MenuPanel") || btn.closest(".tw-whiteboard-tldraw-container")) : null;
        if (!panel) return null;
        return panel.querySelector("#TD-Page") || null;
    }

    // Resolve the app for a button: prefer a fresh fiber walk from the live
    // trigger; fall back to the last app cached on the button so a click is
    // never dropped by a transient React state.
    function resolveApp(btn, captured) {
        var live = liveTrigger(btn) || captured;
        var app = live ? findAppFrom(live) : null;
        if (!app && live !== captured && captured) {
            app = findAppFrom(captured);
        }
        if (app) {
            btn._lithicApp = app;
        } else {
            app = btn._lithicApp || null;
        }
        return app;
    }

    function getSortedPages(app) {
        var pages = app.document.pages || {};
        return Object.keys(pages)
            .map(function (id) { return pages[id]; })
            .sort(function (a, b) { return (a.childIndex || 0) - (b.childIndex || 0); });
    }

    function getCurrentIndex(app) {
        var pages = getSortedPages(app);
        var currentId = app.appState.currentPageId;
        for (var i = 0; i < pages.length; i++) {
            if (pages[i].id === currentId) return i;
        }
        return -1;
    }

    function refreshDisabled(app, prevBtn, nextBtn) {
        var idx = app ? getCurrentIndex(app) : -1;
        var count = app ? getSortedPages(app).length : 0;
        prevBtn.disabled = idx <= 0;
        nextBtn.disabled = idx === -1 || idx >= count - 1;
        // The glyph swap is pure CSS (:disabled), so nothing here mutates DOM.
    }

    function navigate(trigger, prevBtn, nextBtn, direction, event) {
        if (event) {
            event.preventDefault();
            event.stopPropagation();
        }
        var app = resolveApp(nextBtn, trigger);
        if (!app) return;
        var pages = getSortedPages(app);
        var idx = getCurrentIndex(app);
        if (idx === -1) return;
        var target = direction === "prev" ? idx - 1 : idx + 1;
        if (target < 0 || target >= pages.length) return;
        app.changePage(pages[target].id);
        refreshDisabled(app, prevBtn, nextBtn);
    }

    function instrument(trigger) {
        if (trigger.dataset.lithicPageNav === "1") return;

        // Clear any stale page-nav buttons already in the panel (e.g. from a
        // previous trigger instance) so there is never more than one pair.
        var panel = trigger.parentElement;
        if (panel) {
            var stale = panel.querySelectorAll(".lithic-wb-page-prev, .lithic-wb-page-next");
            for (var s = 0; s < stale.length; s++) {
                stale[s].remove();
            }
        }

        // The buttons go to the RIGHT of the page select dropdown, as
        // siblings of the trigger inside the menu panel's flex row.
        var prevBtn = makeButton("prev");
        var nextBtn = makeButton("next");
        trigger.insertAdjacentElement("afterend", prevBtn);
        prevBtn.insertAdjacentElement("afterend", nextBtn);
        trigger.dataset.lithicPageNav = "1";

        // Keep tldraw (pointer handlers) and the radix dropdown trigger from
        // ever seeing these interactions.
        var stop = function (event) { event.stopPropagation(); };
        prevBtn.addEventListener("pointerdown", stop, true);
        nextBtn.addEventListener("pointerdown", stop, true);
        prevBtn.addEventListener("mousedown", stop, true);
        nextBtn.addEventListener("mousedown", stop, true);

        prevBtn.addEventListener("click", function (event) {
            navigate(trigger, prevBtn, nextBtn, "prev", event);
        });
        nextBtn.addEventListener("click", function (event) {
            navigate(trigger, prevBtn, nextBtn, "next", event);
        });

        refreshDisabled(resolveApp(nextBtn, trigger), prevBtn, nextBtn);

        // Recompute the disabled state whenever the current page name changes
        // (dropdown selection, page create/delete, or the wiki-side board
        // switcher loading a different board into this widget).
        var labelObserver = new MutationObserver(function () {
            refreshDisabled(resolveApp(nextBtn, trigger), prevBtn, nextBtn);
        });
        labelObserver.observe(trigger, { childList: true, subtree: true, characterData: true });
    }

    function scan() {
        var containers = document.querySelectorAll(".tw-whiteboard-tldraw-container");
        for (var i = 0; i < containers.length; i++) {
            var trigger = containers[i].querySelector("#TD-Page");
            if (!trigger) continue;
            if (trigger.dataset.lithicPageNav !== "1") {
                instrument(trigger);
            }
            var prev = trigger.nextElementSibling;
            var next = prev ? prev.nextElementSibling : null;
            if (prev && next &&
                prev.classList && prev.classList.contains("lithic-wb-page-prev") &&
                next.classList && next.classList.contains("lithic-wb-page-next")) {
                var app = findAppFrom(trigger) || null;
                if (app) {
                    prev._lithicApp = app;
                    next._lithicApp = app;
                }
                refreshDisabled(app, prev, next);
            }
        }
    }

    exports.startup = function () {
        if (typeof window === "undefined" || typeof document === "undefined") return;

        var scheduled = false;
        var observer = new MutationObserver(function () {
            if (scheduled) return;
            scheduled = true;
            setTimeout(function () {
                scheduled = false;
                scan();
            }, SCAN_DEBOUNCE_MS);
        });
        observer.observe(document.body, { childList: true, subtree: true });

        scan();
    };

})();"},"$:/Lithic/Patches/Whiteboard/PageNavStyle":{"title":"$:/Lithic/Patches/Whiteboard/PageNavStyle","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* Prev/next page buttons beside the tldraw page-select dropdown,
   mounted by $:/Lithic/Patches/Whiteboard/PageNav.js */

.lithic-wb-page-prev,
.lithic-wb-page-next {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    width: 38px !important;
    height: 30px !important;
    margin: 0 2px !important;
    padding: 0 !important;
    box-sizing: border-box;
    position: relative !important;
    top: 5px !important;
    border: 1px solid transparent;
    border-radius: 4px !important;
    background-color: transparent !important;
    color: inherit;
    cursor: pointer;
}

.lithic-wb-page-prev:hover:not(:disabled),
.lithic-wb-page-next:hover:not(:disabled) {
    background-color: rgba(var(--lithic-c-foreground-rgb), 0.22) !important;
}

.lithic-wb-page-prev:active:not(:disabled),
.lithic-wb-page-next:active:not(:disabled) {
    background-color: rgba(var(--lithic-c-foreground-rgb), 0.32) !important;
}

.lithic-wb-page-prev:disabled,
.lithic-wb-page-next:disabled {
    opacity: 0.35;
    cursor: default;
}

/* Both glyphs are always in the DOM; :disabled picks which one shows. */
.lithic-wb-page-prev .lithic-wb-glyph,
.lithic-wb-page-next .lithic-wb-glyph {
    display: inline-flex;
    line-height: 0;
}

.lithic-wb-page-prev .lithic-wb-glyph-dot,
.lithic-wb-page-next .lithic-wb-glyph-dot {
    display: none;
}

.lithic-wb-page-prev:disabled .lithic-wb-glyph-chevron,
.lithic-wb-page-next:disabled .lithic-wb-glyph-chevron {
    display: none;
}

.lithic-wb-page-prev:disabled .lithic-wb-glyph-dot,
.lithic-wb-page-next:disabled .lithic-wb-glyph-dot {
    display: inline-flex;
}

.lithic-wb-page-prev .lithic-wb-glyph-chevron svg,
.lithic-wb-page-next .lithic-wb-glyph-chevron svg {
    display: block;
    width: 18px;
    height: 18px;
}

.lithic-wb-page-prev .lithic-wb-glyph-dot svg,
.lithic-wb-page-next .lithic-wb-glyph-dot svg {
    display: block;
    width: 10px;
    height: 10px;
}

/* Touch pointers: this menu panel and the layout's own 400px bar are layered
   over the same top strip as tldraw's right-hand cluster (undo/redo/zoom/
   styles), and on a phone there is not room for all three side by side. Two
   collisions have to be undone without moving anything on a desktop, where
   there is room for all of them.

   First: the page arrows sat behind that bar (the bar is layered over the
   board), so the last two panel items were unclickable. They move to a second
   line below the panel. They are taken out of the flow rather than given a
   grid row, because the panel shares its flex row with the right-hand cluster:
   any in-flow child that grows makes the row taller and stretches that cluster
   with it, so one extra line on the left was silently growing undo/redo on the
   right. Positioned absolutely under the panel they add no height, and
   overflow:visible lets them show below the panel's own 41px box. */
@media (pointer: coarse) {
    #TD-MenuPanel {
        position: relative !important;
        height: 41px !important;
        overflow: visible !important;
    }

    /* The inline row only needed the 5px nudge up because the row itself was
       40px tall; on their own line the buttons sit flush and use margins. */
    .lithic-wb-page-prev,
    .lithic-wb-page-next {
        position: absolute !important;
        top: 41px !important;
        margin: 4px 2px !important;
    }

    .lithic-wb-page-prev {
        left: 0 !important;
    }

    .lithic-wb-page-next {
        left: 42px !important;
    }
}

/* Second: that bar is centred at width:400px, so on a landscape phone narrower
   than about 844px its right end covers undo/redo. It starts just right of the
   panel instead and is capped so it stops short of the cluster's 222px, which
   leaves the space next to the panel as the only place the bar can live. The
   board search field is the one item that flexes, so the fixed buttons beside
   it never spill back over the cluster.

   124px clears the widest page label a board is likely to reach - the panel
   measures 99px at "Page 1" and grows about a pixel per character, so even
   "Page 1234" stays clear of the bar. */
@media (pointer: coarse) and (max-width: 1024px) {
    .tw-whiteboard-layout-top-bar {
        box-sizing: border-box !important;
        left: 124px !important;
        width: auto !important;
        max-width: calc(100% - 356px) !important;
        justify-content: flex-start !important;
    }

    .tw-whiteboard-layout-top-bar > span:first-child {
        flex: 0 1 auto;
        min-width: 0;
    }

    /* The search field carries an inline 230px width, so it cannot shrink on
       its own - measured from the viewport it stays inside the bar's cap and
       never slides over the buttons beside it. */
    .lithic-wb-search-input {
        width: min(230px, calc(100vw - 574px)) !important;
    }
}

/* A short landscape phone (iPhone SE and friends) cannot give the board search
   field a width worth having beside the four buttons, so the field steps aside
   and leaves them all at full size. The dropdown arrow next to it still opens
   the board list. */
@media (pointer: coarse) and (max-width: 620px) {
    .lithic-wb-search-input {
        display: none !important;
    }
}"},"$:/Lithic/Patches/Whiteboard/SaveButtonStyle":{"title":"$:/Lithic/Patches/Whiteboard/SaveButtonStyle","tags":"$:/tags/Stylesheet","type":"text/css","text":"/* Ensure the save-wiki button in the whiteboard top bar
   matches the size and pill styling of the adjacent buttons */

.lithic-wb-save-btn {
    display: inline-flex;
    align-items: center;
    vertical-align: middle;
    margin: 0 1px;
}

.lithic-wb-save-btn button {
    display: inline-flex !important;
    align-items: center;
    justify-content: center;
    width: 3.2em !important;
    height: 2.0em !important;
    border-radius: 1.0em !important;
    background: var(--lithic-c-menu-bg) !important;
    border: 1px solid rgba(var(--lithic-c-menu-fg-rgb), 0.2) !important;
    cursor: pointer;
    padding: 0 !important;
    box-sizing: border-box !important;
}

.lithic-wb-save-btn button:hover {
    background: color-mix(in srgb, var(--lithic-c-menu-fg) 10%, var(--lithic-c-menu-bg)) !important; /* slightly lighter on hover */
}

/* Scale up the SVG icon inside */
.lithic-wb-save-btn button svg {
    width: 1.2em;
    height: 1.2em;
}

/* Hide the broken Font selector in the Tldraw style menu */
#TD-Styles-Font-Container {
    display: none !important;
}



/* Comptext injected stickies are ALWAYS transparent (targeted via 'c001' UUID suffix) */
div[id$="c001"][data-shape="sticky"] .c-gLGcPs {
    background-color: transparent !important;
    text-shadow: none !important;
    box-shadow: none !important;
}

/* Replace the 'Insert Media' button icon with a Command Palette icon */
#TD-PrimaryTools-Image svg {
    display: none !important;
}

#TD-PrimaryTools-Image .c-lkmCgW::after {
    content: "$:>/";
    font-family: monospace;
    font-size: 10px;
    font-weight: bold;
    color: currentColor;
    display: inline-block;
    line-height: 1;
}

"},"$:/Lithic/Patches/Whiteboard/WriteBehind.js":{"title":"$:/Lithic/Patches/Whiteboard/WriteBehind.js","type":"application/javascript","module-type":"startup","text":"/*\
title: $:/Lithic/Patches/Whiteboard/WriteBehind.js
type: application/javascript
module-type: startup

Write-behind buffer for whiteboard (application/tldr) tiddlers.

The linonetwo/tw-whiteboard widget writes the entire board JSON back to the
wiki store on every (500ms-debounced) stroke and dispatches tm-auto-save-wiki,
which serializes the ENTIRE wiki store whenever autosave is enabled. As the
wiki grows, every stroke pays O(wiki size) in serialization cost.

This patch decouples the board's working memory from the store, following the
same model as the native "edit tiddler" dialog: the whiteboard's state is
transient and is only written back to the tiddler (and thus to the wiki file
on save) when the user actually saves the wiki or closes the board.

1. Text writes to application/tldr tiddlers are buffered in memory instead of
   hitting the store, so strokes fire no change events and never dirty the wiki.
2. The buffer is flushed BEFORE any real wiki save (tm-save-wiki /
   tm-auto-save-wiki) by hooking the root widget's dispatchEvent, so the
   serializer always includes the latest board state.
3. The buffer is flushed on pagehide/beforeunload as a crash safety net (this
   also covers the board's final unmount write when the app closes).

Trade-offs (strict mode):
- Until the wiki is saved, other consumers of the board tiddler (<$wb-image>
   widgets, the comptext paste bridge, other open boards) see the last saved
   state, not live strokes. Use the whiteboard layout's Save button to commit.
- A hard crash before a save loses strokes made since the last save.
\*/
(function(){
"use strict";

exports.name = "lithic-whiteboard-write-behind";
exports.platforms = ["browser"];
exports.after = ["startup"];
exports.synchronous = true;

exports.startup = function() {
	if(typeof window === "undefined" || typeof $tw === "undefined") {
		return;
	}

	var buffer = {};
	var originalSetText = $tw.wiki.setText.bind($tw.wiki);

	function isWhiteboard(title) {
		var tiddler = $tw.wiki.getTiddler(title);
		return !!(tiddler && tiddler.fields.type === "application/tldr");
	}

	function flushBuffer() {
		var titles = Object.keys(buffer);
		if(titles.length === 0) {
			return;
		}
		var pending = buffer;
		buffer = {};
		for(var i = 0; i < titles.length; i++) {
			var title = titles[i];
			if(!$tw.wiki.tiddlerExists(title)) {
				continue; // board was deleted before the flush
			}
			try {
				originalSetText(title, undefined, undefined, pending[title]);
			} catch(e) {
				console.error("[Lithic] Whiteboard write-behind flush failed for " + title, e);
			}
		}
	}

	// 1. Buffer text writes to whiteboard tiddlers; everything else passes through.
	$tw.wiki.setText = function() {
		var title = arguments[0],
			field = arguments[1],
			value = arguments[3];
		if(typeof value !== "string" || !isWhiteboard(title)) {
			return originalSetText.apply(null, arguments);
		}
		// Text writes to a whiteboard are buffered (the heavy per-stroke path).
		if(!field || field === "text") {
			buffer[title] = value;
			return;
		}
		// The widget re-writes `type` on every save; if it is already the same
		// value, skip it entirely so the per-stroke write cannot stamp a new
		// `modified` timestamp (which would fire a change event and dirty the wiki).
		if(field === "type" && $tw.wiki.getTiddler(title).fields.type === value) {
			return;
		}
		return originalSetText.apply(null, arguments);
	};

	// 2. Flush before any real wiki save so the serializer sees the latest board.
	function installSaveHook() {
		if(!$tw.rootWidget || $tw.rootWidget.__lithicWriteBehindHooked) {
			return;
		}
		$tw.rootWidget.__lithicWriteBehindHooked = true;
		var originalDispatch = $tw.rootWidget.dispatchEvent;
		$tw.rootWidget.dispatchEvent = function(event) {
			if(event && (event.type === "tm-save-wiki" || event.type === "tm-auto-save-wiki")) {
				flushBuffer();
			}
			return originalDispatch.call(this, event);
		};
	}
	installSaveHook();
	if(!$tw.rootWidget) {
		var tries = 0;
		var hookTimer = setInterval(function() {
			tries++;
			installSaveHook();
			if($tw.rootWidget || tries > 100) {
				clearInterval(hookTimer);
			}
		}, 50);
	}

	// 3. Crash safety net: flush on page teardown.
	window.addEventListener("pagehide", flushBuffer);
	window.addEventListener("beforeunload", flushBuffer);
};

})();
"},"$:/Lithic/Widgets/multi-wb-image.js":{"title":"$:/Lithic/Widgets/multi-wb-image.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/Lithic/Widgets/multi-wb-image.js
type: application/javascript
module-type: widget

A widget to extract and display images from a list of whiteboard tiddlers.
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var MultiWbImageWidget = function(parseTreeNode,options) {
	this.initialise(parseTreeNode,options);
};

/*
Inherit from the base widget class
*/
MultiWbImageWidget.prototype = new Widget();

/*
Render this widget into the DOM
*/
MultiWbImageWidget.prototype.render = function(parent,nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();

    var container = this.document.createElement("div");
    container.className = this.className || "multi-wb-image-container";

    for (var i = 0; i < this.boardTitles.length; i++) {
        var boardTitle = this.boardTitles[i];
        var imgNode = this.document.createElement("img");

        if(this.width) {
            imgNode.setAttribute("width", this.width);
        }
        if(this.height) {
            imgNode.setAttribute("height", this.height);
        }

        var src = this.extractImageSrc(boardTitle);
        if(src) {
            imgNode.setAttribute("src", src);
        } else {
            imgNode.setAttribute("alt", "Whiteboard image not found: " + boardTitle);
            imgNode.style.border = "1px dashed var(--lithic-c-code-warn)";
            imgNode.style.display = "inline-block";
            if (!this.width) imgNode.style.width = "100px";
            if (!this.height) imgNode.style.height = "100px";
        }
        container.appendChild(imgNode);
    }

	parent.insertBefore(container,nextSibling);
	this.domNodes.push(container);
};

MultiWbImageWidget.prototype.extractImageSrc = function(boardTitle) {
    var tiddler = this.wiki.getTiddler(boardTitle);
    if (!tiddler || !tiddler.fields.text) return null;
    try {
        var doc = JSON.parse(tiddler.fields.text);
        if (doc && doc.document && doc.document.assets) {
            var assets = doc.document.assets;
            for (var id in assets) {
                var asset = assets[id];
                if (asset.type === "image") {
                    return asset.src;
                }
            }
        }
    } catch(e) {
        console.error("MultiWbImageWidget parse error", e);
    }
    return null;
};

/*
Compute the internal state of the widget
*/
MultiWbImageWidget.prototype.execute = function() {
	var boardsText = this.getAttribute("boards") || this.getAttribute("text") || this.getAttribute("list") || "";

    var titles = [];
    var lines = boardsText.split("\n");
    for(var i=0; i<lines.length; i++) {
        var line = lines[i].trim();
        if(!line) continue;
        if(line.startsWith("[[") && line.endsWith("]]")) {
            titles.push(line.substring(2, line.length - 2));
        } else {
            titles.push(line);
        }
    }

	this.boardTitles = titles;
	this.width = this.getAttribute("scale") || this.getAttribute("width", "80%");
	this.height = this.getAttribute("height");
    this.className = this.getAttribute("class");
};

/*
Selectively refreshes the widget if needed. Returns true if the widget or any of its children needed re-rendering
*/
MultiWbImageWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if(changedAttributes.scale || changedAttributes.boards || changedAttributes.text || changedAttributes.list || changedAttributes.width || changedAttributes.height || changedAttributes["class"]) {
		this.refreshSelf();
		return true;
	}
    if (this.boardTitles) {
        for (var i = 0; i < this.boardTitles.length; i++) {
            if (changedTiddlers[this.boardTitles[i]]) {
                this.refreshSelf();
                return true;
            }
        }
    }
	return false;
};

exports["multi-wb-image"] = MultiWbImageWidget;
exports["multi.wb.image"] = MultiWbImageWidget;

})();
"},"$:/Lithic/Widgets/trigger-print.js":{"title":"$:/Lithic/Widgets/trigger-print.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/Lithic/Widgets/trigger-print.js
type: application/javascript
module-type: widget

A hidden widget that triggers window.print() after a delay, and then cleans up.
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var PrintWidget = function(parseTreeNode,options) {
	this.initialise(parseTreeNode,options);
};

PrintWidget.prototype = new Widget();

PrintWidget.prototype.render = function(parent,nextSibling) {
	this.parentDomNode = parent;
	this.execute();

	if (typeof window !== "undefined" && !this.printed) {
		this.printed = true; // prevent infinite loops on re-render
		var self = this;
		var delay = parseInt(this.getAttribute("delay", "1000"), 10);

		setTimeout(function() {
			window.print();
		}, delay);
	}
};

PrintWidget.prototype.execute = function() {};
PrintWidget.prototype.refresh = function() { return false; };

exports["trigger-print"] = PrintWidget;

})();
"},"$:/Lithic/Widgets/wb-image.js":{"title":"$:/Lithic/Widgets/wb-image.js","type":"application/javascript","module-type":"widget","text":"/*\
title: $:/Lithic/Widgets/wb-image.js
type: application/javascript
module-type: widget

A widget to extract and display an image from a whiteboard's internal JSON assets.
\*/
(function(){

/*jslint node: true, browser: true */
/*global $tw: false */
"use strict";

var Widget = require("$:/core/modules/widgets/widget.js").widget;

var WbImageWidget = function(parseTreeNode,options) {
	this.initialise(parseTreeNode,options);
};

/*
Inherit from the base widget class
*/
WbImageWidget.prototype = new Widget();

/*
Render this widget into the DOM
*/
WbImageWidget.prototype.render = function(parent,nextSibling) {
	this.parentDomNode = parent;
	this.computeAttributes();
	this.execute();

    var imgNode = this.document.createElement("img");
    if(this.width) {
        imgNode.setAttribute("width", this.width);
    }
    if(this.height) {
        imgNode.setAttribute("height", this.height);
    }
    if(this.className) {
        imgNode.className = this.className;
    }

    var src = this.extractImageSrc();
    if(src) {
        imgNode.setAttribute("src", src);
    } else {
        // Fallback or error
        imgNode.setAttribute("alt", "Whiteboard image not found");
        imgNode.style.border = "1px dashed var(--lithic-c-code-warn)";
        imgNode.style.display = "inline-block";
        if (!this.width) imgNode.style.width = "100px";
        if (!this.height) imgNode.style.height = "100px";
    }

	parent.insertBefore(imgNode,nextSibling);
	this.domNodes.push(imgNode);
};

WbImageWidget.prototype.extractImageSrc = function() {
    var tiddler = this.wiki.getTiddler(this.boardTitle);
    if (!tiddler || !tiddler.fields.text) return null;
    try {
        var doc = JSON.parse(tiddler.fields.text);
        if (doc && doc.document && doc.document.assets) {
            var assets = doc.document.assets;
            for (var id in assets) {
                var asset = assets[id];
                if (asset.type === "image") {
                    if (this.imageName && asset.fileName === this.imageName) {
                        return asset.src;
                    }
                    if (this.assetId && asset.id === this.assetId) {
                        return asset.src;
                    }
                }
            }
            // If neither name nor assetId provided, fallback to the FIRST image found
            if (!this.imageName && !this.assetId) {
                for (var firstId in assets) {
                    if (assets[firstId].type === "image") {
                        return assets[firstId].src;
                    }
                }
            }
        }
    } catch(e) {
        console.error("WbImageWidget parse error", e);
    }
    return null;
};

/*
Compute the internal state of the widget
*/
WbImageWidget.prototype.execute = function() {
	var boardTitle = this.getAttribute("board", this.getVariable("currentTiddler"));
	if (boardTitle && boardTitle.startsWith("[[") && boardTitle.endsWith("]]")) {
		boardTitle = boardTitle.substring(2, boardTitle.length - 2);
	}
	this.boardTitle = boardTitle;
	this.imageName = this.getAttribute("name");
    this.assetId = this.getAttribute("assetId");
	this.width = this.getAttribute("width", "80%");
	this.height = this.getAttribute("height");
    this.className = this.getAttribute("class");
};

/*
Selectively refreshes the widget if needed. Returns true if the widget or any of its children needed re-rendering
*/
WbImageWidget.prototype.refresh = function(changedTiddlers) {
	var changedAttributes = this.computeAttributes();
	if(changedAttributes.board || changedAttributes.name || changedAttributes.assetId || changedAttributes.width || changedAttributes.height || changedAttributes["class"] || changedTiddlers[this.boardTitle]) {
		this.refreshSelf();
		return true;
	}
	return false;
};

exports["wb-image"] = WbImageWidget;

})();
"},"$:/lithic/buttons/FullscreenWhiteboard":{"title":"$:/lithic/buttons/FullscreenWhiteboard","tags":"$:/tags/PageControls","text":"\whitespace trim
