					<$edit-comptext tag="input" tiddler="$:/temp/whiteboard-comptext-input" field="text" class="tc-edit-texteditor lithic-floating-comptext-input" placeholder="Type command or link..." style="width: 100%; border: 1px solid <<colour table-border>>; padding: 8px; font-size: 1.2em; outline: none; box-sizing: border-box; background: <<colour page-background>>; box-shadow: 0 4px 10px rgba(0,0,0,0.1); border-radius: 4px;" />
